#!/usr/bin/env bash
# Bundle item 166_env_videos_1122 (thread "Videos: Environment committee meetings", 22 Nov 2569). Asked by "Site: Update automatically
# three times a day" (22 Nov). ONE self-contained file: the videos are embedded below as base64 tar.gz (sha256-checked).
# New videos on parliamentx.com/environment/2569 (1080x1920, Thai voice + English subtitles burned in, one version):
#   - main 42 (Tue 24 Nov 2569) BEFORE-meeting video  -> index.html meeting 42 (date card added by item 165)
#   - main 41 (17 Nov 2569) AFTER-meeting video        -> index.html meeting 41, beside its live before-meeting video
#   - climate subcommittee 4 (19 Nov 2569) AFTER-meeting video -> sub-climate.html meeting 4, beside its live before video
# APPLY AFTER 165_edu_env_energy_nov22 (it adds the 41 summary, the 42 date card and the climate 4 summary).
# Surgical: adds only these videos to the "media" field of those meetings (live videos, listen-button audio and every
# other field kept), fills their CAPS caption tracks, makes the share pages (video_share.py CARD_BIG=1), re-applies
# no_video_dl, refreshes the home newest-4 video list + Environment 2569 snapshot "v", then moves the mp4s to the video
# repos (video_offload.py). Idempotent; no git, no network. Needs $HUB ($BUILD optional).
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
L="$HUB/environment/2569"
test -f "$L/index.html" -a -f "$L/sub-climate.html" -a -f "$L/meetings.json" -a -f "$L/sub-climate.json" -a -f "$HUB/index.html" \
  || { echo "166_env_videos_1122: Environment pages missing" >&2; exit 1; }
python3 - "$L" <<'PY0' || { echo "166_env_videos_1122: apply 165_edu_env_energy_nov22 first (meeting 42 date card / 41 summary / climate 4 missing)" >&2; exit 1; }
import json, sys
L = sys.argv[1]
def ms(p): return {f"{m['n']}|{m['date']}": m for m in json.load(open(f'{L}/{p}', encoding='utf-8'))}
a, c = ms('meetings.json'), ms('sub-climate.json')
assert '42|2026-11-24' in a and '41|2026-11-17' in a and '4|2026-11-19' in c
assert not a['41|2026-11-17'].get('pending') and a['41|2026-11-17'].get('headline')
assert not c['4|2026-11-19'].get('pending')
PY0
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d > "$W/p.tgz"
echo "90a1eb0113c760bf2b841d2b70cb520960a67146eb6422666c550a0521a57384  $W/p.tgz" | sha256sum -c --quiet - || { echo "166_env_videos_1122: payload checksum mismatch" >&2; exit 1; }
mkdir "$W/m"; tar -xzf "$W/p.tgz" -C "$W/m"
SRC="$W/m"
for v in v42pre:176 v41:269 sub-climate-v4:137; do f=${v%%:*}; want=${v##*:}
  test -s "$SRC/$f.mp4" -a -s "$SRC/$f.th.vtt" || { echo "166_env_videos_1122: $f missing in payload" >&2; exit 1; }
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$SRC/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<1.5 else 1)" || { echo "166_env_videos_1122: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$SRC/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "166_env_videos_1122: $f size $wh" >&2; exit 1; }
  head -1 "$SRC/$f.th.vtt" | grep -q '^WEBVTT' || { echo "166_env_videos_1122: $f vtt header" >&2; exit 1; }
done
mkdir -p "$L/media" "$L/img"
for f in "$SRC"/*.mp4 "$SRC"/*.vtt; do b=$(basename "$f"); cmp -s "$f" "$L/media/$b" || cp -f "$f" "$L/media/$b"; done
for f in "$SRC"/*.jpg; do b=$(basename "$f"); cmp -s "$f" "$L/img/$b" || cp -f "$f" "$L/img/$b"; done
python3 - "$HUB" <<'PY'
import json, os, sys
HUB = sys.argv[1]; L = os.path.join(HUB, 'environment', '2569')
ADD = json.loads(r"""{
"index.html": {
"42|2026-11-24": [
{
"src": "media/v42pre.mp4",
"poster": "img/poster42pre.jpg",
"vtt": "media/v42pre.th.vtt",
"kind": "pre",
"label": "วิดีโอก่อนการประชุม",
"dur": "2:56",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "42p"
}
],
"41|2026-11-17": [
{
"src": "media/v41.mp4",
"poster": "img/poster41.jpg",
"vtt": "media/v41.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "4:29",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "41"
}
]
},
"sub-climate.html": {
"4|2026-11-19": [
{
"src": "media/sub-climate-v4.mp4",
"poster": "img/poster-sub-climate-4.jpg",
"vtt": "media/sub-climate-v4.th.vtt",
"kind": "post",
"label": "วิดีโอสรุปผลการประชุม",
"dur": "2:17",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "climate-4"
}
]
}
}""")
JSONS = {'index.html': 'meetings.json', 'sub-climate.html': 'sub-climate.json'}
CMP = dict(ensure_ascii=False, separators=(',', ':'))
ser = lambda a: json.dumps(a, **CMP).replace('</', '<\\/')
changed = []

def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.relpath(path, HUB))

def merged(old, new):
    old = json.loads(json.dumps(old or {}))
    vids = old.get('videos') or ([old['video']] if old.get('video') else [])
    cks = {v['ck'] for v in new}
    vids = [v for v in vids if v.get('ck') not in cks]
    for v in new:
        v = dict(v)
        loc = os.path.join(L, v['src'])
        if os.path.exists(loc): v['size'] = os.path.getsize(loc)
        vids.append(v)
    vids.sort(key=lambda v: 0 if v.get('kind') == 'pre' else 1)   # before-meeting video first (VIDEO ORDER)
    old['video'] = vids[0]; old['videos'] = vids
    return old

def jline(lines, prefix, dump):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f'{prefix} line not found once'
    line = lines[idx[0]]; body = line[len(prefix):]; tail = body[len(body.rstrip().rstrip(';')):]
    val = json.loads(body[:len(body) - len(tail)])
    assert prefix + dump(val) + tail == line, f'{prefix} line does not round-trip; not touching it'
    return idx[0], val, tail

for page, want in ADD.items():
    p = os.path.join(L, page); lines = open(p, encoding='utf-8').read().split('\n')
    i, arr, tail = jline(lines, 'const DATA=', ser)
    keys = {f"{m['n']}|{m['date']}": m for m in arr}
    for k, new in want.items():
        assert k in keys, f'{page}: meeting {k} not on the page'
        keys[k]['media'] = merged(keys[k].get('media'), new)
    lines[i] = 'const DATA=' + ser(arr) + tail
    i, caps, tail = jline(lines, 'const CAPS=', lambda a: json.dumps(a, ensure_ascii=False))
    for new in want.values():
        for v in new:
            caps[v['ck']] = open(os.path.join(L, v['vtt']), encoding='utf-8').read()
    lines[i] = 'const CAPS=' + json.dumps(caps, ensure_ascii=False) + tail
    put(p, '\n'.join(lines))
    p = os.path.join(L, JSONS[page]); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f'{JSONS[page]} does not round-trip; not touching it'
    mk = {f"{m['n']}|{m['date']}": m for m in ms}
    for k, new in want.items():
        assert k in mk, f'{JSONS[page]}: meeting {k} missing'
        mk[k]['media'] = merged(mk[k].get('media'), new)
    put(p, json.dumps(ms, ensure_ascii=False, indent=1))

# home page: newest-4 video list (same rules as archive/hub/home.py) + Environment 2569 snapshot "v" counts
ms = json.load(open(os.path.join(L, 'meetings.json'), encoding='utf-8'))
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read(); dec = json.JSONDecoder()
mark = 'const HH = '
if t.count(mark) == 1:
    i = t.index(mark) + len(mark); hh, _ = dec.raw_decode(t[i:])
    old_s = ser(hh['videos'])
    assert t.count(old_s) == 1, 'home: video list text not found once'
    env = []
    for m in ms:
        for v in (m.get('media') or {}).get('videos') or []:
            env.append(dict(n=m['n'], date=m['date'], year=2569, who='กมธ.ทรัพยากรธรรมชาติและสิ่งแวดล้อม', label=v.get('label') or 'วิดีโอสรุป',
                            dur=v.get('dur', ''), poster='environment/2569/' + v['poster'] if v.get('poster') else '',
                            headline='' if m.get('pending') else (m.get('headline') or ''), href=f"environment/2569/#read-{m['n']}"))
    seen = {(v['href'], v['poster']) for v in hh['videos']}
    vids = hh['videos'] + [v for v in env if (v['href'], v['poster']) not in seen]
    vids.sort(key=lambda v: v['date'], reverse=True)
    t = t.replace(old_s, ser(vids[:4]), 1)
else:
    print('166_env_videos_1122: home page has no HH list (skipped)')
dm = 'const DATA = '
assert t.count(dm) == 1, 'home: DATA not found once'
j = t.index(dm) + len(dm); hub, _ = dec.raw_decode(t[j:])
nv = {(m['n'], m['date']): len((m.get('media') or {}).get('videos') or []) for m in ms}
assert any(c.get('id') == 'environment' for c in hub), 'home: Environment committee not in DATA'
for c in hub:
    if c.get('id') != 'environment':
        continue
    for y in c.get('years', []):
        if y.get('year') != 2569:
            continue
        for s in y.get('snap') or []:
            want = nv.get((s['n'], s['date']))
            if want is not None and s.get('v') != want:
                a = ser(s); s['v'] = want; b = ser(s)
                assert t.count(a) == 1, f'home: snapshot entry {s["n"]} not found once'
                t = t.replace(a, b, 1)
put(p, t)
print('166_env_videos_1122: changed', len(changed), 'text files:', ', '.join(changed) or 'none (already applied)')
PY
CARD_BIG=1 python3 "$BUILD/video_share.py" "$L" https://parliamentx.com/environment/2569 2569
python3 "$BUILD/no_video_dl.py" "$L/s"
python3 "$BUILD/no_video_dl.py" --check "$L"
for f in v-42-pre v-41 v-climate-4; do test -f "$L/s/$f.html" || { echo "166_env_videos_1122: share page s/$f.html missing" >&2; exit 1; }; done
python3 - "$L" <<'PY'
import json, sys
L = sys.argv[1]
for page, ks in (('index.html', ('41', '42')), ('sub-climate.html', ('4',))):
    t = open(f'{L}/{page}', encoding='utf-8').read()
    vs = [l for l in t.split('\n') if l.startswith('const VSHARE=')]
    assert vs and all(f'"{k}":' in vs[0] for k in ks), f'{page}: VSHARE missing {ks}'
d = {f"{m['n']}": m for m in json.load(open(f'{L}/meetings.json', encoding='utf-8'))}
assert [v['kind'] for v in d['41']['media']['videos']] == ['pre', 'post'], 'meeting 41: want pre + post'
assert [v['kind'] for v in d['42']['media']['videos']] == ['pre'], 'meeting 42: want pre'
c = {f"{m['n']}": m for m in json.load(open(f'{L}/sub-climate.json', encoding='utf-8'))}
assert [v['kind'] for v in c['4']['media']['videos']] == ['pre', 'post'], 'climate 4: want pre + post'
print('166_env_videos_1122 pages OK')
PY
VR=/mnt/project-files/archive/video_repos
if [ "${ENV_VIDEOS_TEST_NO_OFFLOAD:-}" = 1 ]; then echo "166_env_videos_1122: offload skipped (sandbox test only)"
else
  test -f $VR/ACTIVE || { echo "166_env_videos_1122: video repos not active; refusing to leave videos on the main site" >&2; exit 1; }
  grep -qxF '*.mp4' $HUB/.gitignore 2>/dev/null || { echo "166_env_videos_1122: $HUB/.gitignore has no *.mp4 line" >&2; exit 1; }
  python3 "$BUILD/video_offload.py" "$HUB" --report $VR/OFFLOAD_166_env_videos_1122.md || python3 "$BUILD/video_offload.py" "$HUB"
  python3 /mnt/project-files/archive/check/video_host_check.py "$HUB"
  if find "$L" -name '*.mp4' | grep -q .; then echo "166_env_videos_1122: mp4 still on the main site after offload" >&2; exit 1; fi
fi
echo "166_env_videos_1122 OK"
exit 0
